(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["gd"] = {"ui":{"skip":"Leum gu susbaint","back":"← Air ais gu AI-gile","lang.button":"Cànan: {name}","lang.dialog":"Tagh cànan","lang.search":"Lorg cànan","lang.none":"Chan eil cànan a’ freagairt","lang.notYet":"Chan eil {name} air eadar-theangachadh fhathast","theme.aria":"Atharraich an t-ùrlar: soilleir, dorcha no dubh","theme.toLight":"Atharraich gu ùrlar soilleir","theme.toDark":"Atharraich gu ùrlar dorcha","theme.toBlack":"Atharraich gu ùrlar dubh (fìor dhubh, furasta air sgrìnichean OLED)","words.underline":"Cuir loidhne fo na faclan seo air an duilleag","words.underlineHelp":"Cuir an luchag air facal dotagach no thoir gnogag air gus faicinn dè tha e a’ ciallachadh.","index.title":"AI-gile: an sgioba AI agad, air aon bhòrd","index.description":"Is e bòrd kanban a th’ ann an AI-gile airson sgiobaidhean còdaidh AI. Bidh iad ag obair fhad ’s a tha thu nad chadal; gheibh thu aon chrann beag de rudan airson co-dhùnadh, deuchainn agus gabhail ris.","hero.logoAlt":"Ìomhaigheag bhòrd AI-gile","hero.h1.html":"An sgioba AI agad, air aon&nbsp;bhòrd.","hero.alpha":"🐣 Ro-alpha dùinte","hero.alphaTitle":"Tràth agus neo-chrìochnaichte: tapadh leibh airson feuchainn air!","hero.lede":"Bidh iad a’ togail fhad ’s a tha thu nad chadal. Tha thu a’ dùsgadh gu aon chrann beag: beagan cheistean, beagan rudan airson deuchainn, daoimean purpaidh no dhà. Briog, gabh ris, air ais chun a’ chofaidh agad.","dl.windows":"Aplacaid Windows","dl.browser":"Ruith e sa bhrabhsair agad","dl.messenger":"📱 Messenger airson d’ fhòn","dl.soon":"Dhan ath-ghoirid","dl.notify":"🔔 Innis dhomh nuair a dh’fhosglas e","dl.notifySmall":"Alpha no beta","hero.secondary":"Agile, ach chan fheum an sgioba cofaidh seasamh a-chaoidh. (Bidh stand-ups aca co-dhiù.)","pitch.h2":"AI-gile ann an uiread de dh’fhaclan ’s as toil leat","pitch.lede":"Tagh fad, o aon fhacal gu 144. Tha gach fad na thuairisgeul fhèin, sgrìobhte airson a mheud. Slaod an sleamhnachan no cleachd na saighdean.","pitch.rangeLabel":"Fad ann am faclan","pitch.dice":"🎲 tionndadh eile","pitch.words.one":"{n} fhacal","pitch.words.other":"{n} facal","pitch.letters.one":"{n} litir","pitch.letters.other":"{n} litir","pitch.chars.one":"{n} charactar","pitch.chars.other":"{n} caractar","count.line.html.one":"{n} chairt air a’ bhòrd an-dràsta","count.line.html.other":"{n} cairt air a’ bhòrd an-dràsta","people.humans.html.one":"👥 {n} duine","people.humans.html.other":"👥 {n} duine","people.agents.html.one":"🤖 {n} àidseant","people.agents.html.other":"🤖 {n} àidseantan","people.working.html.one":"⚡ {n} ag obair an-dràsta","people.working.html.other":"⚡ {n} ag obair an-dràsta","features.aria":"Dè a nì e","f.pile.h":"Aon chrann dhutsa","f.pile.html":"Tha <b>Dhutsa</b> a’ cumail a h-uile rud a tha a’ feitheamh ort, thar gach pròiseact: ceistean, rudan airson deuchainn, obraichean nach urrainn ach dhut fhèin a dhèanamh. Tha do chiudha ag innse dè th’ ann an ath-ghnothach agus dè cho fada ’s a bheir e.","f.sleep.h":"Sgiobaidhean a bhios ag obair fhad ’s a tha thu nad chadal","f.sleep.p":"Tha stiùiriche agus sgioba de dh’àidseantan AI aig gach pròiseact. Cuir beachd air cairt agus dùisgidh an sgioba, nì iad an obair agus bheir iad air ais i le ceumannan as urrainn do dhuine claoidhte a leantainn.","f.tester.h":"Bidh deuchainniche AI a’ sgrùdadh an toiseach","f.tester.p":"Mus ruig dad thu, leanaidh deuchainniche na ceumannan ann an lethbhreac dhen aplacaid agus seallaidh e na chunnaic e, le glacadh-sgrìn. Dèan sùil air an fheadhainn a shoirbhich agus gabh riutha le aon bhriogadh.","f.proof.h":"Dearbhadh, chan e geallaidhean","f.proof.p":"Seallaidh gach lìbhrigeadh na dh’atharraich: na faidhlichean, an diff, na glacaidhean-sgrìn. Chan fheum thu gach aplacaid fhosgladh airson faicinn a bheil e deiseil.","f.chat.h":"Dèan cabadaich le do stiùirichean","f.chat.p":"Rèile mar Discord: aon ìomhaigheag airson gach pròiseact, daoimeanan purpaidh airson na tha gad iarraidh. Cuir teachdaireachd gu stiùiriche le beachd; nì iad cairtean agus plana dheth, le putan ✅ Go.","f.tidy.h":"Cumaidh e fhèin òrdail","f.tidy.p":"Thèid cairtean co-cheangailte a phasgadh nan aon, thèid tiotalan measgaichte a cheartachadh, agus cumaidh sgrùdadh tòcan an còd caol. Nas lugha ri ghluasad eatorra, nas lugha ri smaoineachadh.","f.private.h":"Leatsa, air a’ choimpiutair agad","f.private.li1":"Ruithidh am bòrd air an inneal agad fhèin agus freagraidh e dhutsa a-mhàin.","f.private.li2":"Tha DMan prìobhaideach eadar daoine crioptaichte o cheann gu ceann.","f.private.li3":"Chan eil cunntasan, luchd-leantainn no briosgaidean ann.","f.lang.h":"Nad chànan fhèin","f.lang.p":"Còrr is 120 cànan, bhon Duitsis, a’ Chuimris agus Seapanais gu spùinneadair, Yoda agus Klingon, le leum luath air ais gu Beurla airson a’ bheàrlagair.","f.service.h":"Bho bheachd gu seirbheis fhìor","f.service.p":"An do thog thu rudeigin le AI a tha daoine a-nis a’ cleachdadh? Comharraich e mar sheirbheis agus cuidichidh am bòrd thu ga ruith gu math: sgrùdaidhean uptime, duilleag staid phoblach, tachartasan le cunntas sgrìobhte, atharrachaidhean a dh’fheumas Go, lethbhric-ghlèidhidh air an sgrùdadh gach latha. Ionnsaichidh Cuideachadh gach ceum dhut mar a thèid thu.","msgr.h2":"AI-gile Messenger: an sgioba agad nad phòcaid","msgr.p1":"Bruidhinn ris an sgioba AI agad gun am bòrd fhosgladh. Dèan cabadaich le stiùirichean nam pròiseactan agad agus le do charaidean, agus faic ceumannan deuchainn cairt is freagair iad, uile bhon fhòn agad.","msgr.p2":"Airson a cheangal, sganaich còd QR air a’ bhòrd agad. A’ chiad turas? Seallaidh còmhradh demo càirdeil dhut mar a tha cùisean.","msgr.when":"Android an toiseach, an uairsin tionndadh-lìn airson fònaichean agus iPhone.","msgr.who":"Stiùiriche a’ phròiseict agad","msgr.b1":"Tha an càradh airson a’ mhodh dhorcha deiseil. A bheil thu ag iarraidh nan ceumannan deuchainn?","msgr.b2":"Tha, mas e do thoil e!","msgr.b3":"1. Fosgail Roghainnean. 2. Tagh Dorcha. A bheil e a’ coimhead ceart?","tl.aria":"Loidhne-ama on chiad chòmhradh chun a’ mhapa-rathaid","tl.h2":"On chiad chabadaich gu na tha romhainn","tl.lede":"Cinn-latha agus amannan fìor, san roinn-tìde agad fhèin. Às dèidh an-diugh is e am plana a th’ ann, gun cheann-latha a ghealltainn.","tl.today":"An-diugh","tl.planned":"san dealbh","tl.cards.one":"{n} chairt","tl.cards.other":"{n} cairt","join.h2":"Thig an sàs","join.lede":"Tha AI-gile ga thogail le fear neònach feusagach le AuDHD agus beagan strì le slàinte-inntinn, agus le mòran àidseantan foighidneach. Tha e prìobhaideach an-dràsta, ann an alpha dùinte le caraidean. A bheil thu ag iarraidh deuchainn nuair a dh’fhosglas e?","join.btn":"Clàraich ùidh","join.small":"Cuiridh sinn post-d thugad, agus chan eil a bharrachd","footer.tag":"AI-gile. Gun luchd-leantainn, gun bhriosgaidean, gun chofaidh stand-up.","footer.licence":"Cead gnìomhachais","footer.status":"Inbhe","footer.privacy":"Na chumas sinn","footer.thanks":"Gairmean le taing do ChilledChat","form.sending":"Ga chur…","form.failed":"Cha do dh’obraich sin: feuch a-rithist uaireigin eile.","form.offline":"Cha b’ urrainn ruighinn air AI-gile: feuch a-rithist uaireigin eile.","form.keep":"Cha chleachd sinn seo ach airson freagairt a thoirt dhut, agus an uair sin sguabaidh sinn às e. Gun luchd-leantainn, gun bhriosgaidean.","form.keepLink":"Na chumas sinn","interest.title":"AI-gile: innis dhomh nuair a dh’fhosglas an alpha","interest.description":"Fàg do phost-d airson cluinntinn cuin a dh’fhosglas alpha no beta dùinte AI-gile.","interest.h1":"🔔 Innis dhomh nuair a dh’fhosglas e","interest.lede":"Tha AI-gile ann am ro-alpha dùinte. Fàg do phost-d agus sgrìobhaidh sinn aon turas, nuair a bhios àite dhut.","interest.email":"Do phost-d","interest.which":"Dè an deuchainn?","interest.alpha":"Alpha dùinte: tràth, garbh, tòrr atharraichean","interest.beta":"Beta: nas seasmhaiche, nas fhaide air adhart","interest.both":"An dàrna fear, ge brith dè thig an toiseach","interest.submit":"Cuir air an liosta mi","interest.thanks":"Tapadh leat! Tha thu air an liosta.","licence.title":"AI-gile: cead gnìomhachais","licence.description":"A’ cleachdadh AI-gile san gnìomhachas agad? Cuir iarrtas a-steach airson cead gnìomhachais an-asgaidh.","licence.h1":"📜 Cead gnìomhachais","licence.lede":"A’ cleachdadh AI-gile san obair? Innis dhuinn cò thu agus dè a nì thu. Ma nì e deagh, tha an cead an-asgaidh.","licence.company":"Companaidh","licence.website":"Làrach-lìn","licence.what":"Dè a nì thu","licence.how":"Mar a chuidicheas e an saoghal","licence.email":"Post-d","licence.submit":"Cuir a-steach","licence.thanks":"Tapadh leat! Freagraidh sinn air a’ phost-d.","status.title":"Inbhe AI-gile","status.h1":"Inbhe AI-gile","status.quiet":"Sàmhach gu leòr","status.intro":"A bheil AI-gile ag obair an-dràsta? Bidh an duilleag seo a’ sgrùdadh na làraich-lìn, co-roinneadh nam bòrd, nan gairmean agus an luchdaidh a-nuas gach 5 mionaidean.","status.up":"Ag obair (fhreagair e ann an {ms} ms)","status.slow":"Cha do fhreagair e an sgrùdadh mu dheireadh, a’ feuchainn a-rithist","status.down":"Sìos: cha do fhreagair e an dà sgrùdadh mu dheireadh","status.svc.web":"Làrach-lìn","status.svc.web.offers":"An làrach seo: dè th’ ann an AI-gile, agus foirm na h-ùidhe","status.svc.boards":"Co-roinneadh bhòrd","status.svc.boards.offers":"Bùird phoblach, teachdaireachdan eadar caraidean agus cuiridhean","status.svc.calls":"Gairmean","status.svc.calls.offers":"Guth, video agus co-roinneadh sgrìn ann an AI-gile","status.svc.download":"Luchdadh a-nuas","status.svc.download.offers":"An stàlaichear Windows agus ceanglaichean cuiridh","status.checking":"A’ sgrùdadh…","status.offline":"Chan urrainn ruighinn air seirbheis na h-inbhe an-dràsta (a’ feuchainn a-rithist)","status.updated":"air ùrachadh {ago}","status.justNow":"o chionn mionaid","status.min":"{n} mion. air ais","status.hours":"{n} u. air ais","status.days":"{n} l. air ais","privacy.title":"AI-gile: na chumas sinn","privacy.h1":"Na chumas sinn","privacy.lede":"An tionndadh goirid: dìreach na chuireas tu thugainn, agus chan ann fada.","privacy.only":"Dìreach na chuireas tu thugainn: na sgrìobhas tu ann am foirm, mar do phost-d. Chan eil dad eile mu do dhèidhinn.","privacy.sealed":"Tha e air a sheulachadh gus nach urrainn dhan fhrithealaiche againn a leughadh: anns a’ bhrabhsair agad mus fhàg e (air brabhsair nas sine, cho luath ’s a ruigeas e). Chan urrainn ach am bòrd againn fhèin fhosgladh.","privacy.server":"Thèid a sguabadh às an fhrithealaiche cho luath ’s a ruigeas e am bòrd againn. Ma bhios dad ann fhathast an dèidh 30 latha, thèid a sguabadh às co-dhiù.","privacy.board":"Cumaidh sinn e air a’ bhòrd againn dìreach gus am freagair sinn thu, agus an uair sin sguabaidh sinn às an sin e cuideachd.","privacy.none":"Gun luchd-leantainn, gun bhriosgaidean, gun anailis.","privacy.local":"Fuirichidh do chànan agus do roghainn soilleir no dorcha anns a’ bhrabhsair agad fhèin. Cha tèid an cur thugainn idir.","privacy.ask":"Airson ’s gun tèid a sguabadh às nas luaithe? Freagair am post-d againn is innis dhuinn.","live.h2":"Seall air ga thogail, beò","live.caption":"Tha gach cairt falaichte: chì thu cumadh na h-obrach, chan e na faclan.","live.watching.one":"beò: {n} a’ coimhead","live.watching.other":"beò: {n} a’ coimhead","live.last.now":"Chaidh a’ chairt mu dheireadh a ghluasad an-dràsta fhèin","live.last.min.one":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} mhionaid","live.last.min.other":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} mionaidean","live.last.hour.one":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} uair a thìde","live.last.hour.other":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} uairean a thìde","live.last.day.one":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} latha","live.last.day.other":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} làithean","live.offline":"Tha am bòrd beò a’ gabhail anail. Till a dh’aithghearr.","live.cols":"Backlog|Ri dhèanamh|Ga dhèanamh|An sgioba a’ sgrùdadh|Dhutsa ri test|Dhan sgioba|Deiseil","pitch.words.two":"{n} fhacal","pitch.words.few":"{n} faclan","pitch.letters.two":"{n} litir","pitch.letters.few":"{n} litrichean","pitch.chars.two":"{n} charactar","pitch.chars.few":"{n} caractaran","count.line.html.two":"{n} chairt air a’ bhòrd an-dràsta","count.line.html.few":"{n} cairtean air a’ bhòrd an-dràsta","tl.cards.two":"{n} chairt","tl.cards.few":"{n} cairtean"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotan.","Tiomnaichte."]},{"n":2,"texts":["Kanban robotach.","Àidseantan, òrdail.","Beachdan, togte."]},{"n":3,"texts":["Kanban airson robotan.","Bidh beachdan nan gleusan.","Kanban àidseant, saor."]},{"n":5,"texts":["Bòrd kanban le àidseantan ga ruith.","Sgrìobh cairtean. Togaidh àidseantan.","Saor, ionadail, deuchainnichte, rudeigin gòrach."]},{"n":8,"texts":["Bòrd kanban saor far am bi àidseantan AI ag obair.","Sgrìobh beachd. Togaidh àidseantan e. Gabhaidh tu ris.","Agile airson aon duine agus mòran robotan foighidneach."]},{"n":13,"texts":["Bòrd kanban air a’ choimpiutair agad far an togar na cairtean le àidseantan AI.","Sgrìobh beachd air a’ bhòrd. Togaidh sgioba de dh’àidseantan e agus sgrùdaidh deuchainniche e.","Saor, gun chunntasan, gun luchd-leantainn: bòrd, beagan robotan, agus thusa os an cionn."]},{"n":21,"texts":["AI-gile: bòrd kanban airson obrachadh le àidseantan còdaidh AI. Togaidh iadsan na cairtean; nì thusa deuchainn orra is gabhaidh tu riutha.","Gheibh gach pròiseact stiùiriche agus sgioba de dh’àidseantan AI. Cuir beachd air cairt sam bith agus tòisichidh an sgioba air obair.","Bòrd saor pearsanta a ruitheas air do choimpiutair fhèin. Is e robotan an luchd-obrach. Is e thusa an tè no am fear a their ‘tha’."]},{"n":34,"texts":["Cuiridh tu beachdan air bòrd. Tionndaidhidh sgioba de dh’àidseantan AI iad gu gleusan obrach, nì iad deuchainn orra, agus bheir iad air ais thugad iad le ceumannan airson feuchainn. Chan eil dad deiseil gus an can thusa e.","Tha AI-gile na bhòrd kanban dachaigh a thog Rich le tòrr cuideachaidh bho na h-àidseantan a tha e a-nis a’ stiùireadh. Tha e an-asgaidh, a’ ruith air do choimpiutair, agus air a cho-roinn le caraidean, chan e reic.","Smaoinich air bòrd kanban àbhaisteach, le colbhan o Backlog gu Deiseil, ach gu bheil na cairtean air an togail le àidseantan AI. Bheir iad aithris air adhartas, faighnichidh iad nuair a tha iad steigte, agus feitheamh iad ri do làmh-suas an-còmhnaidh."]},{"n":55,"texts":["Is e bòrd kanban a th’ ann an AI-gile far a bheil an sgioba air a dèanamh de dh’àidseantan AI. Tha stiùiriche aig gach pròiseact a dhealbhas an obair agus cuidichean a thogas i. Nuair a bhios gleus deiseil, feuchaidh deuchainniche AI e agus gabhaidh e glacadh-sgrìn, agus an uairsin ruigidh e do chrann. Gabh ris, no cuir beachd agus nì iad ath-obair air.","Thòisich e mar dhòigh aig aon neach air sùil a chumail air tòrr seiseanan còdaidh AI aig an aon àm, agus dh’fhàs e na bhòrd ceart. Ruithidh e air d’ inneal, chan eil cunntas a dhìth, agus chan eil luchd-leantainn ann. Tha e an-asgaidh. Tha e cuideachd neo-chrìochnaichte, mar sin cuir roimhe cliathaichean garbha agus iongnadh an dràsta ’s a-rithist.","Seo an dreach onarach. Feumaidh tu fhathast na beachdan a bhith agad, agus feumaidh tu fhathast na toraidhean a sgrùdadh. Is e na nì AI-gile gach rud eatorra: cumaidh e na cairtean an òrdugh, dùisgidh e an àidseant cheart nuair a chuireas tu beachd, seallaidh e dè dìreach a dh’atharraich, agus cumaidh e a h-uile rud nad aon chrann ghoirid."]},{"n":89,"texts":["Is e bòrd kanban saor a th’ ann an AI-gile a ruitheas tu air do choimpiutair fhèin. An àite dhaoine, tha sgioba de dh’àidseantan AI aig gach pròiseact: stiùiriche a thionndaidheas do bheachdan gu cairtean agus plana, agus cuidichean a thogas na cairtean a-rèir prìomhachais. Nuair a tha rudeigin togte, leanaidh deuchainniche AI na ceumannan deuchainn agus seallaidh e dhut na chunnaic e. An uairsin feitheamh e ann an aon chrann air a bheil Dhutsa. Gabhaidh tu ris, no cuiridh tu beachd agus bheir an sgioba oidhirp eile. Chan ruig dad Deiseil às d’ aonais.","Beagan ghleusan nach biodh dùil agad riutha. Cumaidh faire na h-oidhche an colbh Ri dhèanamh làn fhad ’s a tha thu nad chadal, a’ taghadh chairtean nach fheum freagairt bhuat. Seallaidh cunntair thòcan dhut dè an uiread a chleachd na h-àidseantan an-diugh agus an t-seachdain seo, agus cuiridh No Token Mode stad air an caitheamh. Faodaidh tu teachdaireachdan a chur gu caraidean, agus tha teachdaireachdan prìobhaideach crioptaichte o cheann gu ceann. Bruidhnidh am bòrd mu 120 cànan, a’ gabhail a-steach Duitsis, Flemis, spùinneadair agus Klingon. Chan eil bonn sam bith a’ cosg, agus chan eil duine feuchainn ri a reic riut.","Is e pròiseact beag pearsanta a th’ ann an AI-gile, chan e companaidh. Bha Rich ag iarraidh coimhead às dèidh grunn phròiseactan còdaidh AI gun a h-uile aplacaid fhosgladh airson sùil a thoirt orra, agus mar sin thog e fhèin agus na h-àidseantan bòrd dhan sin, agus an uairsin chleachd iad am bòrd gus a’ chòrr dheth a thogail. Tha e ann am ro-alpha dùinte, is e sin gu bheil e ag obair, sa mhòr-chuid, airson dòrlach de charaidean. Chan eil duilleag phrìsean no plana fàis ann. Ma tha e feumail dhut, faodaidh tu iarraidh feuchainn air nuair a dh’fhosglas e."]},{"n":144,"texts":["Is e bòrd kanban a th’ ann an AI-gile airson aon duine agus tòrr àidseantan AI. Ruithidh e air do choimpiutair fhèin agus tha e gu tur an-asgaidh. Cuiridh tu pròiseactan ris, agus gheibh gach pròiseact stiùiriche agus sgioba bheag. Nì thu cabadaich leis an stiùiriche, rudeigin coltach ri Discord, agus mìnichidh tu beachd; tionndaidhidh an stiùiriche e gu cairtean agus plana, agus an uairsin feitheamh e ort gus Go a bhrùthadh. Obraichidh an sgioba tro na cairtean a-rèir prìomhachais, le loidhne-àithne shìmplidh a chaidh a dhèanamh airson modailean cànain. Mus till dad thugad, leanaidh deuchainniche AI na ceumannan ann an lethbhreac dhen aplacaid agus cuiridh e glacadh-sgrìn ris. Ruigidh obair chrìochnaichte do chrann leis na faidhlichean a dh’atharraich agus an diff. Gabhaidh tu ris, no fàgaidh tu beachd agus dùisgidh an sgioba agus feuchaidh iad a-rithist. Chan urrainn ach dhutsa cairt a ghluasad gu Deiseil.","Latha le AI-gile, mu thimcheall. Feasgar fàgaidh tu beagan bheachdan: tha am putan seo san àite cheàrr, bu chòir an liosta sin a bhith air a rèiteachadh, am faigheadh sinn modh dorcha. Falbhaidh tu dhan leabaidh. Leughaidh na h-àidseantan na beachdan, nì iad na h-atharraichean, nì iad deuchainn orra agus bheir iad air ais thugad iad. Ma thraogas Ri dhèanamh, lìonaidh faire na h-oidhche e às a’ Backlog le cairtean nach fheum freagairt bhuat. Sa mhadainn tha aon chrann ghoirid ann: càraid cheistean agus beagan rudan airson feuchainn, gach fear le ceumannan as urrainn do dhuine cadalach a leantainn agus glacadh-sgrìn dheth ag obair. Briogaidh tu tro, gabhaidh tu ris an fheadhainn mhath agus cuiridh tu air ais a’ chòrr. Seallaidh cunntair thòcan na chaidh a chaitheamh, agus tha No Token Mode ann airson seachdainean caola. An uairsin gheibh thu do bhrath-bhìdh, nach urrainn dha na h-àidseantan cuideachadh leis fhathast.","An toiseach, dè nach eil AI-gile. Chan e tòiseachadh-suas a th’ ann, chan eil e ri reic, agus chan eil duine a’ cruinneachadh d’ dàta. Is e bòrd saor a th’ ann a ruitheas air do choimpiutair, gun chunntasan, gun luchd-leantainn agus gun bhriosgaidean. Is e a th’ ann: aon àite òrdail airson a h-uile pròiseact còdaidh AI fhaicinn aig an aon àm, le sgioba de dh’àidseantan a’ dèanamh nan cairtean agus thusa a’ dèanamh nan co-dhùnaidhean. Pasgaidh e cairtean co-cheangailte còmhla, ceartaichidh e tiotalan measgaichte, agus cumaidh e sùil air cho caol ’s a dh’fhanas an còd. Bruidhnidh e mu 120 cànan, bhon Duitsis agus Flemis gu spùinneadair agus Klingon. Faodaidh caraidean teachdaireachdan a chur gu chèile, gu prìobhaideach agus crioptaichte. Chaidh a thogail le Rich agus mòran àidseantan foighidneach, a’ cleachdadh fhèin sa mhòr-chuid. Tha e ann am ro-alpha dùinte, mar sin tha e garbh an siud ’s an seo. Ma tha e coltach le spòrs, iarr gu modhail agus is dòcha gum faigh thu a-steach tràth."]}],"quips":{"1":"Aon fhacal. Dàna. Is dòcha ro dhàna.","3":"Trì faclan. Nas onaraich na a’ mhòr-chuid de dhuilleagan toraidh mar-thà.","8":"Ochd faclan. Fhathast nas giorra na stand-up.","21":"Is e puingean sgeòil a th’ anns na faid, co-dhiù. Gu dearbh is e.","55":"Còig fichead ’s a còig faclan. Chaidh dà chairt a chrìochnachadh fhad ’s a leugh thu sin.","144":"Sin am fear fada. Chan eil 233 ann. Tha na h-àidseantan air a dhol dhan leabaidh."}},"timeline":{"first-idea.name":"A’ chiad bheachd","first-idea.line":"A’ chiad chòmhradh, mus robh còd sam bith ann.","first-board.name":"A’ chiad bhòrd","first-board.line":"Bòrd a bhios a’ cumail sùil air a thogail fhèin: cairtean, colbhan, slaodadh is leigeil às, pròiseactan.","team-roles.name":"Sgioba is dreuchdan","team-roles.line":"Pròifilean àidseant, teamplaidean sgioba, àiteachan agus cò a nì dè.","install.name":"Stàlaich is sgaoilidhean","install.line":"Zip a stàlaicheas caraid, fèin-ùrachadh, seanailean agus tilleadh air ais.","usage-saver.name":"Sàbhaladh cleachdaidh","usage-saver.line":"Tomhais cosgais ruith, cùm an còd caol, sàbhail do chrìoch.","friends.name":"Caraidean is co-roinn","friends.line":"DMan prìobhaideach, ceangal measgaichte, cuiridhean, dreuchdan is pròiseactan co-roinnte.","languages.name":"Cànanan","languages.line":"Gach teacsa sgrìn ann am faidhle cànain, leis an Duitsis is Flemis an toiseach.","ai-tester.name":"Deuchainniche AI","ai-tester.line":"Bidh deuchainniche a’ sgrùdadh gach lìbhrigidh an toiseach agus a’ sealltainn na chunnaic e.","website.name":"An làrach-lìn","website.line":"aigile.lol, an teaser agus an loidhne-ama seo.","streaming.name":"Cabadaich is sruthadh","streaming.line":"Discord, Twitch, OBS, modh sruthadair, GIFs agus emojis.","no-ai.name":"Deasachadh gun AI","no-ai.line":"Bòrd airson daoine a chòdaicheas gun AI, agus bùird phoblach.","night-watch.name":"Faire na h-oidhche","night-watch.line":"Bidh fear-faire agus Scrum Master a’ cumail nan sgiobaidhean air an obair fhad ’s a tha thu nad chadal.","p-more.name":"A h-uile rud eile","p-more.line":"Beachdan nas lugha a tha fhathast a’ feitheamh an cothrom.","p-android.name":"Fòn is Android","p-android.line":"Ruig do bhòrd o fòn, an uairsin aplacaid Android dhùthchasach.","p-release.name":"Alpha is nas fhaide","p-release.line":"Alpha dùinte, an làrach bheò, an uairsin beta.","p-languages.name":"Barrachd chànanan","p-languages.line":"Còrr is ceud cànan, agus modh bogaidh airson luchd-ionnsachaidh.","p-engines.name":"Barrachd einnseanan AI","p-engines.line":"Tagh Claude, Codex no Gemini airson gach àidseant.","p-pro.name":"Cleachdadh proifeasanta","p-pro.line":"Leubailean cunnairt, geataichean cothlamaidh, cairtean thachartasan agus rèilichean-dìon.","p-self.name":"A’ coimhead às do dhèidh","p-self.line":"Modh claoidhte, cuimhneachain fèin-chùraim agus 4:20.","p-servers.name":"Frithealaichean is sgèile","p-servers.line":"Roghainnean frithealaiche cruinneil, dreuchdan agus dealbhadh airson fàs.","p-livestream.name":"Rudan a bharrachd airson sruthadh","p-livestream.line":"Cabadaich Twitch, emojis gnàthaichte agus sealladh beò poblach."},"words":{"button":"📖 Beàrlagair a’ ghnìomhachais","h":"📖 Briathran air am mìneachadh","intro":"Na briathran a choinnicheas tu ann an AI-gile, ann an cainnt shìmplidh: ga thogail, ga atharrachadh gu sàbhailte, ga chumail a’ dol dha na daoine a bhios ga chleachdadh, agus ag obair mar sgioba le AI.","search":"Lorg facal…","none":"Chan eil facal a’ freagairt.","close":"Dùin","count":{"one":"{count} fhacal","other":"{count} faclan"},"groups":[{"id":"build","name":"🛠️ Ga thogail"},{"id":"change","name":"🔀 Ga atharrachadh gu sàbhailte"},{"id":"run","name":"🛎️ A’ ruith seirbheis"},{"id":"team","name":"🤝 Ag obair mar sgioba (agus le AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Pasgan còd a’ phròiseict agus an eachdraidh shlàn de commits, mar as trice cuideachd air GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Loidhne obrach air leth sa chòd, gus an gabh atharraichean a dhèanamh gun suathadh ris a’ phrìomh thionndadh.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Dealbh-sàbhailte dhen chòd, le nota goirid air na dh’atharraich. Faodaidh tu tilleadh gu fear daonnan.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"A’ cur dealbhan-sàbhailte (commits) on choimpiutair seo suas gu GitHub, gus am bi lethbhric orra agus gun tèid an co-roinn."},{"id":"merge","g":"build","word":"Merge","text":"A’ ceangal atharraichean geige air ais dhan phrìomh thionndadh."},{"id":"pr","g":"build","word":"Pull request","text":"Iarraidh gun tèid atharraichean geige a sgrùdadh agus an ceangal ris a’ phrìomh thionndadh.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"A’ cur a’ chòd an òrdugh gun a dhèanamh atharrachadh air na bhios e a’ dèanamh: faidhlichean nas lugha, ainmean nas soilleire, nas lugha de dh’ath-aithris."},{"id":"bug","g":"build","word":"Bug","text":"Rudeigin nach eil ag obair mar bu chòir.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"A’ feuchainn pìos obrach deiseil gus dèanamh cinnteach gu bheil e a’ dèanamh na chaidh iarraidh, mus gabh thu ris.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Giorrachadh air quality assurance (dearbhadh càileachd): na sgrùdaidhean fèin-obrachail a ruitheas mus tèid dad beò. Nuair a tha QA dearg, dh’fhàillig rudeigin, agus chan fhaod e dol beò gus an tèid sin a chàradh.","also":["sgrùdaidhean càileachd","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"A’ cur tionndadh ùr beò, mar eisimpleir air frithealaiche far a bheil daoine ga chleachdadh."},{"id":"release","g":"change","word":"Sgaoileadh","text":"Pasgan de dh’obair chrìochnaichte le ainm air a thèid beò còmhla, le notaichean goirid air na dh’atharraich. Sgrìobhaidh 🚀 Sgaoilidhean na notaichean bho na cairtean deiseil.","also":["sgaoilidhean","release","releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"A’ dol air ais chun an tionndaidh mu dheireadh a dh’obraich nuair a dh’adhbharaicheas tionndadh ùr trioblaid. Ann an AI-gile, nì e liosta-sgrùdaidh de na ceumannan a chuireas air ais e, a chaidh a sgrìobhadh air gach atharrachadh.","also":["rollback","roll-back","tilleadh air ais"]},{"id":"live","g":"change","word":"Beò","text":"An tionndadh fìor a bhios daoine a’ cleachdadh, seach lethbhreac airson rudan fheuchainn. Canaidh luchd-leasachaidh production ris cuideachd.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Atharrachadh","text":"Atharrachadh dealbhaichte air rudeigin air a bheil daoine an eisimeil, air a sgrìobhadh sìos an toiseach: dè, carson, an cunnart, cuin, agus mar a chuirear air ais e. Tòisich fear le 🔀 Tog atharrachadh.","also":["atharrachaidhean","iarrtas atharrachaidh","change request"],"noTip":1},{"id":"risk","g":"change","word":"Cunnart","text":"Rudeigin a dh’fhaodadh a dhol ceàrr, le sgòr air cho coltach ’s a tha e agus cho dona ’s a bhiodh e. Cumaidh ⚠️ Cunnartan iad ann an aon liosta, an sgòr as àirde an toiseach, gach fear le ceann-latha airson sùil eile a thoirt.","also":["cunnartan","clàr chunnartan","risk register"]},{"id":"chgwin","g":"change","word":"Uinneag atharrachaidh","text":"Na h-amannan nuair a dh’fhaodas atharrachaidhean a dhol beò, mar fheasgar Dimàirt sàmhach. Taobh a-muigh uinneig, chan urrainnear cairt atharrachaidh a chrìochnachadh, mur e èiginn a th’ ann.","also":["uinneagan atharrachaidh","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Bhòt luath dìreach mus tèid atharrachadh beò: canaidh gach neach a dh’fheumas aontachadh Go no No go. Cha tèid e air adhart ach nuair a tha iad uile ag aontachadh.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Aonta","text":"A’ feitheamh ri “tha” mus tòisich obair. Feithidh cairt a thogas caraid, no atharrachadh, ann an ✅ Aontaidhean gus an aontaich no an diùlt thu e.","also":["aontaidhean","approval"]},{"id":"quiettime","g":"change","word":"Àm sàmhach","text":"Greis ùine, mar shruth beò, taisbeanadh no an oidhche, nuair nach tèid dad beò. Cumaidh na sgiobaidhean orra ag obair is a’ dèanamh deuchainn, ach feithidh dol beò gus an tig e gu crìch. Ann an àiteachan eile canar change freeze ris.","also":["amannan sàmhach","reothadh atharrachaidh","change freeze"]},{"id":"service","g":"run","word":"Seirbheis","text":"Rudeigin a thog thu air a bheil daoine an eisimeil, mar làrach-lìn no aplacaid, air a chumail suas gus an cùm e ag obair. Cuir strìochag ri “Tha am pròiseact seo na sheirbheis” agus innis dè tha e a’ tabhann, cò bhios ga chleachdadh agus cò tha air dhleastanas.","also":["seirbheisean","service"]},{"id":"uptime","g":"run","word":"Sgrùdadh uptime","text":"Sgrùdadh fèin-obrachail, a h-uile beagan mhionaidean, gu bheil an t-seirbheis agad fhathast a’ freagairt. Ma dh’fhàilligeas e grunn thursan an dèidh a chèile, fosglaidh AI-gile cairt tachartais leis fhèin.","also":["uptime","sgrùdaidhean uptime"]},{"id":"statuspage","g":"run","word":"Duilleag staid","text":"Duilleag phoblach a sheallas a bheil seirbheis ag obair (uaine, orains no dearg) leis an naidheachd as ùire, gus an urrainn dha na daoine a bhios ga cleachdadh sùil a thoirt an àite faighneachd.","also":["duilleagan staid","status page"]},{"id":"incident","g":"run","word":"Tachartas","text":"Rudeigin a tha briste dha na daoine a tha ga chleachdadh an-dràsta, mar an làrach-lìn a bhith sìos. Leumaidh cairt 🔥 tachartais gu toiseach na ciudha: ’s e a chur ag obair a-rithist a’ chiad rud.","also":["tachartasan","incident"]},{"id":"major","g":"run","word":"Tachartas mòr","text":"Tachartas fìor mhòr: mòran dhaoine fo bhuaidh, no airgead no dàta ann an cunnart. Cuiridh aon phutan a h-uile sgioba air (swarm), dùisgidh e cò sam bith a tha air dhleastanas agus iarraidh e naidheachd staid gach 30 mionaid.","also":["tachartasan mòra","major incident"]},{"id":"oncall","g":"run","word":"Air dhleastanas","text":"A bhith nad neach a fhreagras nuair a bhriseas rudeigin, fiù ’s air an oidhche. Tha ball sgioba air dhleastanas aig gach seirbheis a thèid a dhùsgadh an toiseach airson a tachartasan.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Àm freagairt","text":"Dè cho fada ’s a dh’fhaodas cairt feitheamh ris a’ chiad fhreagairt, mar eisimpleir uair a thìde airson tachartas. Às dèidh sin gheibh i gleoc dearg, gus nach tèid dad a dhìochuimhneachadh gu sàmhach. Canar targaid freagairt ris cuideachd.","also":["amannan freagairt","targaid freagairt","response target"]},{"id":"postmortem","g":"run","word":"Sgrùdadh às dèidh an tachartais","text":"Sùil ghoirid air ais às dèidh tachartais: dè thachair, dè chuidich agus dè bu chòir atharrachadh, gun choire a chur air duine sam bith. Chan urrainnear tachartas a dhùnadh às aonais.","also":["post-mortem","postmortem","sgrùdaidhean às dèidh tachartais"]},{"id":"problem","g":"run","word":"Duilgheadas","text":"An t-adhbhar falaichte air cùlaibh aon tachartas no barrachd. Cruinnichidh cairt 🧩 duilgheadais tachartasan a tha a’ tilleadh a-rithist is a-rithist, gus an tèid an t-adhbhar a lorg agus a chàradh gu buan.","also":["duilgheadasan","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Prìomh adhbhar","text":"An dearbh adhbhar a bhris rudeigin, chan e dìreach na chunnaic thu a’ dol ceàrr. Càraich am prìomh adhbhar agus sguiridh an tachartas a thilleadh.","also":["prìomh adhbharan","root cause"]},{"id":"workaround","g":"run","word":"Rathad timcheall","text":"Dòigh air rudan a chumail ag obair gus am bi an dearbh chàradh deiseil, mar rudeigin ath-thòiseachadh nuair a thèid e an sàs. Thèid a sgrìobhadh air cairt an duilgheadais gus nach fheum duine sam bith obrachadh a-mach a-rithist.","also":["rathaidean timcheall","workaround"]},{"id":"knownerror","g":"run","word":"Mearachd aithnichte","text":"Duilgheadas far a bheil an t-adhbhar air a thuigsinn agus aig a bheil rathad timcheall, ach nach deach a chàradh fhathast. Tha 🧩 Mearachdan aithnichte gan liostadh, gus am bi a h-uile duine a’ cleachdadh an rathaid timcheall an àite cladhach a-rithist.","also":["mearachdan aithnichte","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Stiùireadh ceum air cheum airson seòrsa trioblaid aithnichte a chàradh, gus an tèid a dhèanamh san aon dòigh, gu luath, gach turas. Às dèidh tachartas mòr faodaidh an sgioba fear a mholadh dhut airson OK a thoirt dha.","also":["runbooks"]},{"id":"backup","g":"run","word":"Lethbhreac-glèidhidh","text":"Lethbhreac sàbhailte den dàta agad bho roimhe, airson tuiteam air ais air ma thèid rudeigin air chall no a mhilleadh. Nì AI-gile lethbhreac-glèidhidh de na bùird agad gach latha.","also":["lethbhric-ghlèidhidh","backup","backups"]},{"id":"restore","g":"run","word":"Aisig","text":"A’ cur dàta air ais bho lethbhreac-glèidhidh. Chan eil lethbhreac-glèidhidh dha-rìribh a’ cunntadh gus am bi fios agad gun gabh aiseag, mar sin is fhiach feuchainn an-dràsta ’s a-rithist.","also":["aiseag","air aiseag","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Beachdan agus obair nach deach a dhealbhadh fhathast. Chan eil dad an sin ga dhèanamh gus an gluais e gu Ri dhèanamh."},{"id":"sprint","g":"team","word":"Sprint","text":"Ùine ghoirid de dh’obair (seachdain no dhà gu tric) le seata cairtean air a cho-aontachadh airson a chrìochnachadh.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Coinneamh luath: dè rinn gach ball sgioba, dè nì iad an ath rud, agus dè tha gan stad.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Bòrd le colbhan (Ri dhèanamh, Ga dhèanamh, Deiseil) far a bheil cairtean a’ gluasad bho chlì gu deas mar a thèid an obair air adhart."},{"id":"wip","g":"team","word":"WIP limit","text":"Obair ga dhèanamh: an àireamh as motha de chairtean a bu chòir colbh a chumail, gus am cuir an sgioba crìoch air rudan mus tòisich iad air barrachd.","also":["WIP"]},{"id":"dod","g":"team","word":"Mìneachadh air Deiseil","text":"Liosta-sgrùdaidh ghoirid an sgioba air dè tha “crìochnaichte” a’ ciallachadh, mar air a dheuchainn agus air a mhìneachadh, mus tèid cairt a thoirt dhut. Tha a leth-chàraid, am Mìneachadh air Deiseil gu tòiseachadh, ag ràdh cuin a tha cairt soilleir gu leòr airson tòiseachadh.","also":["Definition of Done","Mìneachadh air Deiseil gu tòiseachadh","Definition of Ready"]},{"id":"testpile","g":"team","word":"Cruach deuchainn","text":"Na cairtean deiseil a tha a’ feitheamh riut airson feuchainn, tè às dèidh tè. Gabh ri tè no cuir air ais i le nota, agus thig an ath thè.","also":["cruachan deuchainn","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Sùil air ais air mar a tha an sgioba ag obair, airson aontachadh air aon rud a dhèanamh nas fheàrr. Ann an AI-gile, molaidh retro atharrachadh air dòighean-obrach an sgioba, agus canaidh tu Siuthad no Chan ann fhathast.","also":["retros","sùil air ais","retrospective"]},{"id":"peerreview","g":"team","word":"Lèirmheas co-aoise","text":"Dàrna paidhir shùilean: bidh AI eile a’ sgrùdadh obair gach cairt mus ruig i thu, gus am faigh nas lugha de mhearachdan troimhe.","also":["lèirmheas còd","code review","peer review"]},{"id":"swarm","g":"team","word":"Swarm","text":"A h-uile làmh an sàs: leigidh gach sgioba obair eile seachad gus cuideachadh air aon phròiseact èiginneach gus am bi e air a rèiteachadh. Feithidh pròiseactan eile san eadar-ama.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"An neach a chumas an obair a’ sruthadh: mothaichidh e do chairtean an sàs, brosnaichidh e na sgiobaidhean agus cuiridh e nad chuimhne na tha a’ feitheamh. Ann an AI-gile, nì am Prìomh Scrum Master seo thar gach pròiseict.","also":["Prìomh Scrum Master","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI a dh’obraicheas leis fhèin air gnìomh: a’ leughadh a’ chòd, a’ dèanamh atharraichean, a’ ruith sgrùdaidhean, agus a’ toirt aithisg air ais.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"An aonad anns a bheil cleachdadh AI air a chunntadh: timcheall air beagan litrichean de theacsa air a leughadh no air a sgrìobhadh. Nas lugha de thòcanan, barrachd dhen phlana agad air fhàgail.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Àithne bheag a ruitheas leatha fhèin aig àm sònraichte, m.e. nuair a thòisicheas seisean AI, gus an cluinn an sgioba do bheachdan.","also":["hooks"]}]}};
